<?php
function page_profile(): void {need_login();$u=user();heading('ACCOUNT SETTINGS','My profile','Keep your contact details current and manage your password.');start_form('profile','Personal details');echo '<div class="form-grid">';field('name','Full name','text',$u['name'],true,'maxlength="100"');field('phone','Phone','tel',$u['phone'],false,'maxlength="30"');field('area','Area / district','text',$u['area'],true,'maxlength="100"');echo '</div><p class="muted">Email: '.e($u['email']).' · Role: '.e($u['role']).'</p><h3>Change password (optional)</h3><div class="form-grid">';field('current_password','Current password','password','',false,'autocomplete="current-password"');field('new_password','New password','password','',false,'autocomplete="new-password" minlength="12" maxlength="72"');field('confirm_password','Confirm new password','password','',false,'autocomplete="new-password"');echo '</div>';end_form();}
function page_notifications(): void {need_login();heading('YOUR UPDATES','Notifications','View alerts, report decisions, request updates and volunteer assignments.');start_form('notifications_read','','compact');end_form('Mark all as read');$count=(int)scalar('SELECT COUNT(*) FROM notifications WHERE user_id=?',[user()['id']]);$offset=(max(1,(int)($_GET['p']??1))-1)*15;$rows=all('SELECT * FROM notifications WHERE user_id=? ORDER BY id DESC LIMIT 15 OFFSET '.$offset,[user()['id']]);echo '<section class="card padded">';if(!$rows)empty_state('No notifications yet','Your updates will appear here.');foreach($rows as $n)echo '<a class="notification-item '.(!$n['read_at']?'unread':'').'" href="'.e($n['link']).'"><div>'.icon('notifications').'</div><div><strong>'.e($n['title']).'</strong><p>'.e($n['message']).'</p><small>'.e($n['created_at']).' · '.($n['read_at']?'Read':'Unread').'</small></div></a>';echo '</section>';pager($count,15,'notifications');}
function page_users(): void {need('admin');heading('ACCOUNT MANAGEMENT','Accounts & roles','Manage account roles and access. Disabling an account keeps its history.');$q=trim((string)($_GET['q']??''));echo '<form class="filters" method="get"><input type="hidden" name="page" value="users">';field('q','Search name or email','search',$q,false);echo '<button class="button secondary">Search</button></form>';$count=(int)scalar('SELECT COUNT(*) FROM users WHERE name LIKE ? OR email LIKE ?',['%'.$q.'%','%'.$q.'%']);$offset=(max(1,(int)($_GET['p']??1))-1)*15;$roles=array_column(all('SELECT * FROM roles'),'label','name');echo '<div class="card table-wrap"><table><thead><tr><th>Account</th><th>Area</th><th>Role and access</th></tr></thead><tbody>';foreach(all('SELECT * FROM users WHERE name LIKE ? OR email LIKE ? ORDER BY id LIMIT 15 OFFSET '.$offset,['%'.$q.'%','%'.$q.'%']) as $u){echo '<tr><td><strong>'.e($u['name']).'</strong><small>'.e($u['email']).'</small></td><td>'.e($u['area']).'</td><td><form method="post" class="row-form">';token();echo '<input type="hidden" name="action" value="user_update"><input type="hidden" name="id" value="'.e($u['id']).'">';select('role','Role',$roles,$u['role']);select('active','Account state',[1=>'Active',0=>'Disabled'],$u['active']);echo '<button class="button secondary small">Save</button></form></td></tr>';}echo '</tbody></table></div>';pager($count,15,'users',['q'=>$q]);}
function page_audit(): void {need('admin');heading('ACCOUNTABILITY','Activity audit','Review account activity and coordination decisions in date order.');$q=trim((string)($_GET['q']??''));echo '<form class="filters" method="get"><input type="hidden" name="page" value="audit">';field('q','Search action or detail','search',$q,false);echo '<button class="button secondary">Search</button></form>';$args=['%'.$q.'%','%'.$q.'%'];$where=' WHERE a.action LIKE ? OR a.detail LIKE ?';$count=(int)scalar('SELECT COUNT(*) FROM audit_logs a'.$where,$args);$offset=(max(1,(int)($_GET['p']??1))-1)*20;echo '<div class="card table-wrap"><table><thead><tr><th>Time</th><th>Actor</th><th>Action</th><th>Record</th><th>Detail</th></tr></thead><tbody>';foreach(all('SELECT a.*,u.name actor FROM audit_logs a LEFT JOIN users u ON u.id=a.user_id'.$where.' ORDER BY a.id DESC LIMIT 20 OFFSET '.$offset,$args) as $a)echo '<tr><td>'.e($a['created_at']).'</td><td>'.e($a['actor']??'System').'</td><td>'.e(str_replace('_',' ',$a['action'])).'</td><td>'.e($a['entity']).' #'.e($a['entity_id']).'</td><td>'.e(strtr($a['detail'],['Academic demonstration data enabled'=>'Example records included','Empty operational dataset'=>'No example records included'])).'</td></tr>';echo '</tbody></table></div>';pager($count,20,'audit',['q'=>$q]);}
function page_settings(): void {need('admin');heading('SYSTEM SETTINGS','System settings','Manage the site title and the announcement shown across the application.');$s=array_column(all('SELECT * FROM settings'),'value','name');start_form('settings','Display settings');field('site_name','Site name','text',$s['site_name'],true,'minlength="3" maxlength="60"');textarea('announcement','Site announcement',$s['announcement'],0,500);end_form();}
function chart(string $title,array $rows,string $label,string $value): void {echo '<section class="card padded"><h2>'.e($title).'</h2>';if(!$rows)empty_state('No data yet','Analytics update as records are stored.');$max=max(1,...array_column($rows,$value));foreach($rows as $r)echo '<div class="chart-row"><div><span>'.e($r[$label]).'</span><strong>'.e($r[$value]).'</strong></div><div class="chart-track"><span style="width:'.round($r[$value]/$max*100).'%"></span></div></div>';echo '</section>';}
function page_analytics(): void {need('coordinate');$days=(int)($_GET['days']??30);if(!in_array($days,[7,30,90,365],true))$days=30;heading('DECISION SUPPORT','Incident analytics','Review recorded incidents, affected areas and support requests. These charts show past reports and do not predict future disasters.');echo '<form class="filters" method="get"><input type="hidden" name="page" value="analytics">';select('days','Analysis period',[7=>'Last 7 days',30=>'Last 30 days',90=>'Last 90 days',365=>'Last 365 days'],$days);echo '<button class="button secondary">Update insights</button><a class="button secondary" href="'.url('export',['days'=>$days]).'">Export verified incident CSV</a></form>';$where="r.status IN ('verified','resolved') AND r.created_at>=DATE_SUB(NOW(),INTERVAL $days DAY)";
 metrics([['Verified historical incidents',scalar('SELECT COUNT(*) FROM reports r WHERE '.$where),'Selected period','reports'],['Reported people affected',scalar('SELECT COALESCE(SUM(affected_people),0) FROM reports r WHERE '.$where),'Unverified estimates; may overlap','users'],['Requests fulfilled',scalar("SELECT COUNT(*) FROM assistance_requests WHERE status='fulfilled'"),'All time','assistance'],['Severity changes after review',scalar('SELECT COUNT(*) FROM reports r WHERE '.$where.' AND r.severity<>r.ai_severity'),'Authority changes to the suggested severity','analytics']]);
 echo '<div class="two-columns">';chart('Incidents by disaster category',all('SELECT t.name label,COUNT(*) total FROM reports r JOIN disaster_types t ON t.id=r.type_id WHERE '.$where.' GROUP BY t.name ORDER BY total DESC'),'label','total');chart('Reviewed severity distribution',all('SELECT severity label,COUNT(*) total FROM reports r WHERE '.$where.' GROUP BY severity ORDER BY total DESC'),'label','total');chart('Historical incident hotspots',all('SELECT area label,COUNT(*) total FROM reports r WHERE '.$where.' GROUP BY area ORDER BY total DESC LIMIT 8'),'label','total');chart('Daily incident trend',all('SELECT DATE(created_at) label,COUNT(*) total FROM reports r WHERE '.$where.' GROUP BY DATE(created_at) ORDER BY label DESC LIMIT 14'),'label','total');echo '</div><div class="notice"><strong>Interpret analytics with care</strong><p>These charts use records stored in our system. Counts may include labelled example records and do not measure population risk or predict disasters. Severity suggestions use fixed rules; we have not trained or validated a prediction model.</p></div>';
}
